//! Extraction fidelity, scored from what the deployed API served.
//!
//! **Reported, never gated**, and the reason is not timidity. On the `fake` tier the model
//! answers are written by us, so a threshold here would measure `ds-testkit`. And even on
//! a real tier the corpus is generated by one generator from one template per shape, so
//! its pages are not independent samples: the effective sample size for a per-class claim
//! is nearer "four shapes" than "N pages", and the default corpus is 24 pages against an
//! `Objective::min_pages` of 30. So this test asserts the **machinery** — that scoring the
//! deployed system produces artifacts `ds-adapt` consumes unchanged — and prints the
//! numbers for a human to read.
//!
//! What it would take to quote a fidelity figure is written down in the plan and in
//! `crates/ds-adapt/SPEC.md`: a real labelled corpus, and a real model tier.
//!
//! ## One part of this *is* real on the fake tier
//!
//! Worth knowing before reading the printed table. A hinted born-digital page routes to
//! `born-digital-text`, whose `blocks.merge_native` takes its text from the PDF's **own
//! text layer** — pdfium, no model involved. So on this corpus the `text` column is a
//! genuine measurement of the native-text path against mechanically exact labels (0.95+
//! on prose and two-column), and it would catch a real regression in ingest or stitching.
//!
//! The `layout` and `tables` columns on this tier are not: the regions come from the fake
//! layout model's fixed boxes, which have nothing to do with the page, so they read near
//! zero by construction. Reading that as "layout detection is broken" would be wrong, and
//! reading the `text` column as "extraction quality" would be equally wrong. The columns
//! mean different things on the fake tier, which is the main reason this test prints them
//! separately instead of only the composite.

use std::time::Duration;

use ds_adapt::score::MetricWeights;
use ds_adapt::select::{Objective, PageEval, Trust};
use ds_itest::client::{Client, Upload};
use ds_itest::corpus::{freshened, nonce, Corpus};
use ds_itest::eval::{self, Cost};
use ds_itest::stack::stack_or_skip;

const LIST_VERSION: &str = "example-2026-11-06";

fn repo_root() -> std::path::PathBuf {
    std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")
}

#[tokio::test(flavor = "multi_thread")]
#[ignore = "needs the compose stack: deploy/compose/stack.sh up"]
async fn the_deployed_system_is_scored_and_the_artifacts_are_the_scorer_s_own() -> anyhow::Result<()> {
    let Some(stack) = stack_or_skip().await else { return Ok(()) };
    let client = Client::login(&stack, "ds-api", "ds-api-dev-secret").await?;

    let list_json = std::fs::read_to_string(repo_root().join("config/dag-list.example.json"))?;
    client.activate_dag_list(&list_json, LIST_VERSION).await?;

    let out = std::env::temp_dir().join(format!("ds-itest-fidelity-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&out);
    std::fs::create_dir_all(&out)?;
    let corpus = Corpus::generate(&out.join("corpus"), 1, 1)?;

    let weights = MetricWeights::default();
    let mut evals: Vec<PageEval> = Vec::new();
    let run = nonce("fidelity");

    for (i, entry) in corpus.entries.iter().enumerate() {
        // Hinted, so the router's rules engage: an unhinted born-digital page takes the
        // low-confidence DAG and every document would be scored on the same one.
        let opts = Upload { language: entry.language.clone(), profile: "balanced".into(), doc_type: entry.doc_type_hint.clone() };
        let before_doc = client.metrics(&stack).await?;
        let bytes = freshened(&std::fs::read(&entry.uri)?, &format!("{run}-{i}"));
        let accepted = client.upload(bytes, &format!("{}.pdf", entry.id()), &opts).await?;
        let job = client.await_job(&accepted.job_id, Duration::from_secs(120)).await?;
        anyhow::ensure!(job.state == "done", "{}: {:?}", entry.id(), job.error);
        let after_doc = client.metrics(&stack).await?;
        let hk = accepted.document_hk.clone().ok_or_else(|| anyhow::anyhow!("no document hash key"))?;

        let doc = client.document(&hk).await?;
        let document_ms = eval::document_ms(&job);
        // Tokens for this document alone, as the delta of a cumulative counter around it.
        let tokens = after_doc.delta(&before_doc).sum("model_tokens_total").max(0.0) as u32;
        for p in &doc.pages {
            let page = client.page(&hk, p.page_no as u32).await?;
            let gt = corpus.ground_truth(entry, p.page_no as u32)?;
            let cost = Cost { document_ms, model_seconds: eval::model_seconds(&page), tokens };
            evals.push(eval::page_eval(&entry.id(), &page, &gt, cost, &weights));
        }
    }

    anyhow::ensure!(!evals.is_empty(), "nothing was scored");
    assert!(evals.iter().all(|e| e.trust == Trust::Labelled), "the generated corpus is labelled, so nothing needs a judge");
    assert!(evals.iter().all(|e| !e.failed), "a page failed and so scored nothing");

    // Every metric the corpus can support must be *applicable*, or the composite is
    // quietly averaging fewer things than it appears to.
    assert!(evals.iter().all(|e| e.metrics.text.is_some()), "text similarity did not apply to some page");
    assert!(evals.iter().all(|e| e.metrics.layout.is_some()), "layout F1 did not apply to some page");
    assert!(evals.iter().all(|e| e.metrics.layout_f1_strict.is_some()), "the stricter IoU was not reported");
    assert!(
        evals.iter().any(|e| e.metrics.tables.is_some()),
        "no page scored a table, so the table metric — and TEDS with it — never ran"
    );

    // Tokens per document, which no in-process path can report: `RunRecord::tokens` is 0
    // everywhere because the count never reaches the executor.
    assert!(
        evals.iter().all(|e| e.tokens > 0),
        "a document cost no tokens, so the delta was not attributed to it"
    );

    // ── the artifacts are `ds-adapt`'s own, and it consumes them unchanged ──
    let evals_path = out.join("evals.jsonl");
    ds_adapt::records::write_jsonl(&evals_path, &evals)?;
    let read_back: Vec<PageEval> = ds_adapt::records::read_jsonl(&evals_path)?;
    assert_eq!(read_back.len(), evals.len(), "evals.jsonl did not round-trip");

    let list: ds_router::DagList = serde_json::from_str(&list_json)?;
    let report = ds_adapt::report::render(&list, &read_back, &Objective::default(), None);
    std::fs::write(out.join("report.md"), &report)?;
    assert!(report.contains(&format!("# DAG list `{}`", list.version)));
    assert!(report.contains(&format!("Pages evaluated: **{}**", read_back.len())), "{report}");
    assert!(report.contains("## Candidates"));

    // ── and it refuses to invent a rule it cannot support ──
    //
    // The default objective wants 30 pages per class; this corpus has one per shape. The
    // right behaviour is to emit nothing rather than a per-class rule chosen on a single
    // page, and pinning it here is what stops a later change from quietly lowering the
    // bar.
    let dags = list.dags.clone();
    let selected = ds_adapt::select::select(&read_back, dags, &Objective::default(), "itest-1", None);
    assert!(
        selected.as_ref().is_none_or(|l| l.routing.rules.is_empty()),
        "a rule was selected from {} pages, below the objective's min_pages",
        read_back.len()
    );

    // Reported, not asserted: on the fake tier these numbers describe `ds-testkit`.
    eprintln!("\n── fidelity, tier `{}` ──  (not a quality claim: see this file's header)", stack.tier);
    eprintln!("{:<28} {:>7} {:>7} {:>7} {:>7} {:>8} {:>7}", "page", "text", "lay@.5", "lay@.75", "tables", "order_tau", "qual");
    for e in &read_back {
        let f = |v: Option<f32>| v.map(|v| format!("{v:.3}")).unwrap_or_else(|| "–".into());
        eprintln!(
            "{:<28} {:>7} {:>7} {:>7} {:>7} {:>8} {:>7.3}",
            e.page_id,
            f(e.metrics.text),
            f(e.metrics.layout),
            f(e.metrics.layout_f1_strict),
            f(e.metrics.tables),
            f(e.metrics.order_tau),
            e.quality
        );
    }
    eprintln!("\nartifacts: {}", out.display());
    Ok(())
}
